query:
NODE VALUE `out_degree` SumAgg<INT64> = 0
TABLE `result` { `id` STRING, `degree` INT64 }

MATCH (`src`:`player`)-[`edge`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `src`.@`out_degree` += 1
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id`, `p`.@`out_degree` INTO `result`
}

FOR `row` IN `result`
RETURN `row`.`id` AS `id`, `row`.`degree` AS `degree`
